stylesheets.rules:
:root { color-scheme: light; --canvas: #f4f4ef; --surface: #fbfbf8; --surface-strong: #ffffff; --ink: #17221c; --muted: #647069; --line: #d9ded8; --line-strong: #bec8c0; --green: #0b7548; --green-dark: #075c38; --green-soft: #e2f2e9; --amber: #a66615; --amber-soft: #f7ead7; --red: #b14237; --red-soft: #fae9e6; --shadow: 0 18px 54px rgba(26, 42, 33, 0.08); font-family: Inter, "SF Pro Display", "Segoe UI", Arial, sans-serif; }
* { box-sizing: border-box; }
html { min-width: 1180px; min-height: 100%; background: var(--canvas); }
body { min-width: 1180px; min-height: 100vh; margin: 0px; color: var(--ink); background-image: ; background-position-x: ; background-position-y: ; background-repeat: ; background-attachment: ; background-origin: ; background-clip: ; background-color: ; background-size: 32px 32px; font-size: 15px; line-height: 1.5; }
button, input, select, textarea { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, summary:focus-visible { outline: rgba(11, 117, 72, 0.24) solid 3px; outline-offset: 2px; }
[hidden] { display: none !important; }
.app-header { position: sticky; z-index: 20; top: 0px; display: grid; grid-template-columns: 180px minmax(0px, 1fr) 150px; align-items: center; min-width: 1180px; height: 72px; padding: 0px 38px; border-bottom: 1px solid var(--line); background: rgba(251, 251, 248, 0.96); backdrop-filter: blur(18px); }
.public-demo-banner { display: flex; min-height: 38px; gap: 14px; align-items: center; justify-content: center; padding: 8px 38px; border-bottom: 1px solid rgb(231, 205, 167); color: rgb(113, 68, 13); background: var(--amber-soft); font-size: 11px; }
.public-demo-banner strong { font-size: 11px; }
.public-demo-banner span { color: rgb(128, 85, 29); }
.brand { display: inline-flex; gap: 10px; align-items: center; color: var(--ink); font-size: 14px; font-weight: 800; letter-spacing: 0.07em; text-decoration: none; }
.brand-mark { display: grid; width: 30px; height: 30px; place-items: center; border-radius: 8px; color: white; background: var(--ink); font-size: 13px; }
.main-nav { display: flex; gap: 5px; align-items: center; justify-content: center; }
.main-nav a { padding: 9px 11px; border-radius: 7px; color: var(--muted); font-size: 13px; font-weight: 650; text-decoration: none; transition: color 150ms, background 150ms; }
.main-nav a:hover { color: var(--ink); background: rgb(238, 240, 236); }
.main-nav a.is-active { color: var(--green-dark); background: var(--green-soft); }
.main-nav .nav-disabled { margin-left: 4px; padding: 9px 0px 9px 13px; border-left: 1px solid var(--line-strong); color: rgb(164, 170, 166); font-size: 13px; font-weight: 650; cursor: default; pointer-events: none; user-select: none; }
.service-state { display: flex; gap: 8px; align-items: center; justify-content: flex-end; color: var(--muted); font-size: 12px; }
.state-dot, .proof-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 0 4px var(--green-soft); }
.page { width: min(1420px, 100% - 76px); margin: 0px auto; animation: 240ms ease-out 0s 1 normal both running page-enter; }
@keyframes page-enter { 
  0% { opacity: 0; transform: translateY(5px); }
  100% { opacity: 1; transform: translateY(0px); }
}
.page-heading, .guide-head, .operator-console-head { display: flex; align-items: flex-end; justify-content: space-between; padding-bottom: 30px; border-bottom: 1px solid var(--line-strong); }
.page-heading { padding-top: 78px; }
.page-heading h1, .operator-console-head h2, .guide-head h2 { max-width: 760px; margin: 5px 0px 8px; font-size: clamp(38px, 4vw, 62px); font-weight: 630; letter-spacing: -0.045em; line-height: 1.02; }
.page-heading p:last-child, .guide-head > p, .operator-console-head > p { max-width: 560px; margin: 0px; color: var(--muted); font-size: 16px; }
.eyebrow { margin: 0px; color: var(--green); font-size: 11px; font-weight: 800; letter-spacing: 0.14em; text-transform: uppercase; }
.primary-link, .primary-button, .run-button, .secondary-button, .danger-button, .text-button { display: inline-flex; min-height: 44px; align-items: center; justify-content: center; border: 0px; border-radius: 8px; cursor: pointer; font-weight: 720; text-decoration: none; transition: transform 150ms, background 150ms, border-color 150ms; }
.primary-link, .primary-button, .run-button { padding: 0px 20px; color: white; background: var(--green); }
.primary-link:hover, .primary-button:hover, .run-button:hover { background: var(--green-dark); transform: translateY(-1px); }
.secondary-button { padding: 0px 18px; border: 1px solid var(--line-strong); color: var(--ink); background: var(--surface-strong); }
.secondary-button:hover { border-color: var(--green); color: var(--green-dark); }
.text-button { min-height: 38px; padding: 0px 10px; color: var(--muted); background: transparent; }
.text-button:hover { color: var(--ink); background: rgb(238, 240, 236); }
.danger-button { padding: 0px 18px; color: white; background: var(--red); }
button:disabled { cursor: not-allowed; opacity: 0.45; transform: none !important; }
.overview-page { min-height: calc(-124px + 100vh); }
.overview-status { display: grid; grid-template-columns: repeat(3, 1fr); margin-top: 52px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.overview-status > div { min-height: 178px; padding: 31px 36px; border-left: 1px solid var(--line); }
.overview-status > div:first-child { padding-left: 0px; border-left: 0px; }
.overview-status span, .overview-status small { display: block; color: var(--muted); }
.overview-status span { font-size: 12px; font-weight: 750; letter-spacing: 0.07em; text-transform: uppercase; }
.overview-status strong { display: block; margin: 22px 0px 7px; font-size: 23px; font-weight: 650; }
.overview-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-top: 34px; }
.overview-actions a { display: flex; align-items: center; justify-content: space-between; padding: 25px 28px; border: 1px solid var(--line); border-radius: 10px; color: var(--ink); background: rgba(255, 255, 255, 0.48); font-weight: 680; text-decoration: none; }
.overview-actions a:hover { border-color: var(--green); background: var(--surface-strong); }
.shell { display: grid; grid-template-columns: 330px minmax(0px, 1fr); gap: 42px; min-height: calc(-72px + 100vh); padding: 46px 0px 54px; }
.controls { align-self: start; padding: 32px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); box-shadow: var(--shadow); }
.controls h1 { margin: 7px 0px 10px; font-size: 32px; font-weight: 650; letter-spacing: -0.035em; line-height: 1.08; }
.lede { margin: 0px; color: var(--muted); }
.mode-switch { display: grid; grid-template-columns: 1fr 1fr; gap: 4px; margin: 28px 0px 18px; padding: 4px; border-radius: 9px; background: rgb(234, 237, 233); }
.mode-button { min-height: 38px; border: 0px; border-radius: 6px; color: var(--muted); background: transparent; cursor: pointer; font-size: 13px; font-weight: 700; }
.mode-button.is-active { color: var(--ink); background: white; box-shadow: rgba(24, 38, 30, 0.1) 0px 2px 9px; }
.mode-context { padding: 20px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface-strong); }
.mode-heading { display: flex; gap: 10px; align-items: center; }
.mode-indicator { width: 8px; height: 8px; border-radius: 50%; }
.mode-context p, .control-note { color: var(--muted); font-size: 12px; }
.source-list { margin: 16px 0px 0px; padding: 0px; list-style: none; }
.source-list li { display: flex; justify-content: space-between; padding: 8px 0px; border-top: 1px solid rgb(237, 240, 236); font-size: 12px; }
.source-list strong { font-weight: 680; }
.controls > .run-button { width: 100%; min-height: 52px; justify-content: space-between; margin-top: 18px; }
.button-arrow { font-size: 19px; }
.workspace { min-width: 0px; padding: 9px 0px 0px; }
.workspace-head, .panel-head { display: flex; align-items: center; justify-content: space-between; }
.workspace-head { padding-bottom: 20px; border-bottom: 1px solid var(--line-strong); }
.workspace-head h2 { margin: 5px 0px 0px; font-size: 31px; font-weight: 620; letter-spacing: -0.035em; }
.run-status, .automation-state { padding: 7px 11px; border-radius: 999px; color: var(--muted); background: rgb(231, 234, 230); font-size: 11px; font-weight: 800; letter-spacing: 0.05em; text-transform: uppercase; }
.run-status.is-running, .automation-state.is-active { color: var(--green-dark); background: var(--green-soft); }
.run-status.is-blocked, .automation-state.is-error { color: var(--red); background: var(--red-soft); }
.pipeline { display: grid; grid-template-columns: repeat(5, 1fr); margin: 0px; padding: 22px 0px; border-bottom: 1px solid var(--line); list-style: none; }
.pipeline li { position: relative; display: grid; gap: 2px; padding-right: 14px; color: var(--muted); font-size: 12px; }
.pipeline li::after { position: absolute; top: 12px; right: 8px; width: calc(100% - 30px); height: 1px; background: var(--line); content: ""; transform: translateX(50%); }
.pipeline li:last-child::after { display: none; }
.pipeline .step-number { position: relative; z-index: 1; display: grid; width: 25px; height: 25px; margin-bottom: 7px; place-items: center; border: 1px solid var(--line); border-radius: 50%; background: var(--surface); font-size: 9px; font-weight: 800; }
.pipeline li.is-done .step-number, .pipeline li.is-running .step-number { border-color: var(--green); color: white; background: var(--green); }
.pipeline li.is-blocked .step-number { border-color: var(--red); color: white; background: var(--red); }
.step-state { font-size: 10px; }
.empty-state { display: grid; min-height: 390px; place-items: center; align-content: center; color: var(--muted); text-align: center; }
.signal { display: flex; gap: 6px; align-items: flex-end; height: 44px; margin-bottom: 20px; }
.signal span { width: 5px; border-radius: 4px; background: var(--green); animation: 1.2s ease-in-out 0s infinite alternate none running signal; }
.signal span:nth-child(1) { height: 14px; }
.signal span:nth-child(2) { height: 31px; animation-delay: 100ms; }
.signal span:nth-child(3) { height: 22px; animation-delay: 200ms; }
.signal span:nth-child(4) { height: 39px; animation-delay: 300ms; }
.signal span:nth-child(5) { height: 18px; animation-delay: 400ms; }
@keyframes signal { 
  100% { opacity: 0.38; transform: scaleY(0.7); }
}
.report { padding: 26px 0px; }
.report-meta { display: flex; justify-content: space-between; margin-bottom: 24px; color: var(--muted); font-size: 12px; }
.campaign-goal-summary { display: grid; grid-template-columns: minmax(280px, 1.7fr) repeat(3, minmax(140px, 0.7fr)); border-top: 1px solid var(--line-strong); }
.campaign-goal-summary > div { display: grid; gap: 4px; align-content: center; min-height: 96px; padding: 18px; border-left: 1px solid var(--line); }
.campaign-goal-summary > div:first-child { padding-left: 0px; border-left: 0px; }
.campaign-goal-summary span, .campaign-goal-summary small { color: var(--muted); font-size: 11px; }
.campaign-goal-summary span { font-weight: 720; text-transform: uppercase; }
.campaign-goal-summary strong { font-size: 16px; line-height: 1.35; }
.goal-achievement.is-achieved strong { color: var(--green-dark); }
.goal-achievement.is-not-achieved strong { color: var(--red); }
.goal-achievement.is-pending strong { color: var(--amber); }
.metrics { display: grid; grid-template-columns: repeat(5, 1fr); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.metric { padding: 22px 18px; border-left: 1px solid var(--line); }
.metric:first-child { padding-left: 0px; border-left: 0px; }
.metric span, .change span { display: block; color: var(--muted); font-size: 11px; font-weight: 720; text-transform: uppercase; }
.metric strong { display: block; margin-top: 8px; font-size: 23px; font-weight: 650; }
.decision { display: grid; grid-template-columns: minmax(0px, 1fr) 170px; gap: 36px; align-items: center; padding: 36px 0px; border-bottom: 1px solid var(--line); }
.decision h3 { margin: 6px 0px 9px; font-size: 29px; font-weight: 640; letter-spacing: -0.03em; }
.decision p:last-child, .panel-copy { margin: 0px; color: var(--muted); }
.change { padding: 21px; border-radius: 10px; background: var(--green-soft); }
.change strong { display: block; margin-top: 7px; color: var(--green-dark); font-size: 27px; }
.execution { display: flex; align-items: center; justify-content: space-between; padding: 23px 0px; border-bottom: 1px solid var(--line); }
.execution-line { margin: 4px 0px 0px; font-weight: 650; }
.safety-proof { display: flex; gap: 9px; align-items: center; color: var(--muted); font-size: 12px; }
.proposal-review { display: grid; grid-template-columns: minmax(0px, 1fr) 170px 280px; gap: 24px; align-items: center; margin: 24px 0px 0px; padding: 24px; border: 1px solid rgb(186, 219, 200); border-radius: 11px; background: var(--green-soft); }
.proposal-review h4 { margin: 4px 0px 5px; font-size: 20px; }
.proposal-review p { margin: 0px; color: var(--muted); font-size: 13px; }
.proposal-step-field, .interval-field, .scenario-fields label, .threshold-editor label, .rule-row > label:not(.rule-toggle) { display: grid; gap: 7px; color: var(--muted); font-size: 12px; font-weight: 650; }
.proposal-step-field > span:last-child { display: flex; gap: 7px; align-items: center; color: var(--ink); font-size: 18px; }
.proposal-step-field input { width: 92px; }
.proposal-actions { display: flex; gap: 9px; justify-content: flex-end; }
.proposal-review .automation-message { grid-column: 1 / -1; }
.report-actions { display: flex; justify-content: flex-end; padding-top: 18px; }
.report-actions a { color: var(--green-dark); font-weight: 700; }
.blocked-panel { margin-top: 28px; padding: 28px; border: 1px solid rgb(233, 195, 188); border-radius: 11px; background: var(--red-soft); }
.blocked-panel h3 { margin: 6px 0px; }
.page-fragments, .test-lab, .lab-grid { display: contents; }
.lab-panel, .recommendation-guide, .history-console, .operator-console, .workflow-console, .campaign-console, .evidence-console { padding: 52px 0px 64px; }
.scenario-panel, .automation-panel { min-height: calc(-72px + 100vh); }
.scenario-panel .panel-head, .automation-panel .panel-head { padding-bottom: 24px; border-bottom: 1px solid var(--line-strong); }
.panel-head h3 { margin: 5px 0px 0px; font-size: 28px; font-weight: 630; letter-spacing: -0.03em; }
.panel-index { color: var(--line-strong); font-size: 42px; font-weight: 600; }
.scenario-fields, .threshold-editor { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; padding: 28px 0px 24px; }
input, select, textarea { width: 100%; padding: 0px 12px; border: 1px solid var(--line-strong); border-radius: 7px; color: var(--ink); background: var(--surface-strong); }
input, select { height: 44px; }
textarea { min-height: 104px; padding-top: 11px; padding-bottom: 11px; line-height: 1.5; resize: vertical; }
input:hover, select:hover, textarea:hover { border-color: rgb(151, 164, 154); }
input:focus, select:focus, textarea:focus { border-color: var(--green); }
input[type="checkbox"] { width: 17px; height: 17px; accent-color: var(--green); }
.advanced-metrics { grid-column: 1 / -1; margin-top: 4px; border-top: 1px solid var(--line); }
.advanced-metrics summary { padding: 18px 0px 0px; cursor: pointer; color: var(--green-dark); font-size: 13px; font-weight: 750; }
.advanced-metrics-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; padding: 20px 0px 0px; }
.rule-toggle { gap: 9px; align-items: center; display: flex !important; color: var(--ink) !important; }
.derived-preview { display: grid; grid-template-columns: repeat(5, 1fr); margin-top: 15px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.derived-preview > div { padding: 22px; border-left: 1px solid var(--line); }
.derived-preview > div:first-child { padding-left: 0px; border-left: 0px; }
.derived-preview span { display: block; color: var(--muted); font-size: 11px; font-weight: 720; text-transform: uppercase; }
.derived-preview strong { display: block; margin-top: 6px; font-size: 20px; }
.automation-panel { max-width: 920px; }
.automation-panel > .interval-field { width: 360px; margin: 34px 0px; }
.safety-note { max-width: 760px; margin: 34px 0px; padding: 16px 18px; border-left: 3px solid var(--green); color: var(--muted); background: rgba(255, 255, 255, 0.5); }
.automation-actions, .inline-actions, .evidence-actions { display: flex; gap: 10px; align-items: center; }
.automation-message { min-height: 22px; margin: 14px 0px 0px; color: var(--green-dark); font-size: 13px; font-weight: 650; }
.automation-message.is-error { color: var(--red); }
.automation-timing { color: var(--muted); font-size: 13px; }
.guide-head, .operator-console-head { padding-top: 20px; }
.guide-head h2, .operator-console-head h2 { font-size: 43px; }
.trigger-rules-host { margin-top: 42px; }
.trigger-rules-host > h3, .threshold-title { margin: 0px 0px 17px; font-size: 22px; font-weight: 640; }
.rule-list { border-top: 1px solid var(--line-strong); }
.rule-row { display: grid; grid-template-columns: minmax(250px, 1.3fr) repeat(3, minmax(150px, 0.7fr)); gap: 18px; align-items: center; min-height: 82px; padding: 14px 0px; border-bottom: 1px solid var(--line); }
.rule-row > span { grid-column: 2 / -1; color: var(--muted); font-size: 13px; }
.advanced-rules { border-bottom: 1px solid var(--line-strong); }
.advanced-rules summary { padding: 20px 0px; cursor: pointer; color: var(--green-dark); font-size: 13px; font-weight: 750; }
.advanced-rules[open] summary { border-bottom: 1px solid var(--line); }
.decision-rule-workspace { display: grid; grid-template-columns: 300px minmax(0px, 1fr); gap: 44px; margin-top: 52px; padding: 32px 0px; border-top: 1px solid var(--line-strong); border-bottom: 1px solid var(--line-strong); }
.decision-rule-picker { padding-right: 36px; border-right: 1px solid var(--line); }
.decision-rule-picker > label { display: grid; gap: 8px; color: var(--muted); font-size: 12px; font-weight: 650; }
.decision-rule-picker > p:last-child { margin: 16px 0px 0px; color: var(--muted); font-size: 13px; line-height: 1.6; }
.decision-rule-editor h3 { margin: 5px 0px 10px; font-size: 26px; letter-spacing: -0.025em; }
.selected-rule-formula { max-width: 780px; margin: 0px; color: var(--green-dark); font-size: 15px; font-weight: 650; line-height: 1.55; }
.decision-rule-editor .threshold-editor { grid-template-columns: repeat(2, minmax(0px, 1fr)); padding: 26px 0px 20px; }
.decision-rule-note { margin: 0px; color: var(--muted); font-size: 12px; line-height: 1.55; }
.threshold-editor { padding-top: 0px; }
.guide-actions { display: flex; align-items: center; justify-content: space-between; padding: 22px 0px; border-top: 1px solid var(--line); }
.guide-actions p { margin: 0px; color: var(--muted); }
.matrix-heading { display: flex; align-items: end; justify-content: space-between; gap: 40px; margin-top: 52px; }
.matrix-heading h3 { margin: 5px 0px 0px; }
.matrix-heading > p { max-width: 430px; margin: 0px; color: var(--muted); font-size: 13px; text-align: right; }
.matrix-scroll { overflow: hidden; margin-top: 20px; border: 1px solid var(--line); border-radius: 10px; background: var(--surface); }
.recommendation-matrix { width: 100%; border-collapse: collapse; }
.recommendation-matrix th, .recommendation-matrix td { padding: 16px 18px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; }
.recommendation-matrix th { color: var(--muted); background: rgb(238, 240, 236); font-size: 11px; letter-spacing: 0.06em; text-transform: uppercase; }
.recommendation-matrix td { font-size: 13px; }
.recommendation-matrix tr.is-current td { background: var(--green-soft); }
.decision-history { border-top: 1px solid var(--line); }
.history-tabs { display: flex; gap: 26px; margin: 0px 0px 38px; border-bottom: 1px solid var(--line-strong); }
.history-tabs button { position: relative; min-height: 48px; padding: 0px; border: 0px; color: var(--muted); background: transparent; cursor: pointer; font-weight: 700; }
.history-tabs button[aria-selected="true"] { color: var(--ink); }
.history-tabs button[aria-selected="true"]::after { position: absolute; right: 0px; bottom: -1px; left: 0px; height: 2px; background: var(--green); content: ""; }
.history-tab-panel .operator-console-head { padding-bottom: 30px; }
.history-summary { display: flex; align-items: baseline; justify-content: space-between; padding: 15px 0px; border-top: 1px solid var(--line); color: var(--muted); font-size: 12px; }
.history-summary p { margin: 0px; }
.history-summary strong { margin-right: 5px; color: var(--ink); font-size: 18px; }
.decision-history article { display: grid; grid-template-columns: 180px 1fr 1.5fr 160px; gap: 24px; align-items: start; padding: 25px 0px; border-bottom: 1px solid var(--line); }
.decision-history p, .decision-history h4 { margin: 0px; }
.history-origin p, .decision-history article > p { color: var(--muted); font-size: 13px; }
.history-status { text-align: right; }
.history-status a { color: var(--green-dark); font-size: 12px; }
.history-outcome-link { display: block; margin: 8px 0px 0px auto; padding: 0px; border: 0px; color: var(--green-dark); background: transparent; cursor: pointer; font-size: 12px; text-decoration: underline; }
.history-controls, .history-pagination { display: flex; align-items: center; }
.history-controls { justify-content: space-between; min-height: 62px; }
.history-pagination { gap: 14px; }
.history-pagination span { color: var(--muted); font-size: 12px; }
.history-empty { padding: 80px 0px; color: var(--muted); text-align: center; }
.decision-outcome { min-height: 310px; }
.decision-outcome-head { padding: 4px 0px 26px; border-bottom: 1px solid var(--line-strong); }
.decision-outcome-head h3 { margin: 6px 0px 0px; font-size: 32px; letter-spacing: -0.035em; }
.accepted-decision { display: grid; grid-template-columns: 180px minmax(240px, 0.85fr) 1.2fr 1.35fr; gap: 24px; align-items: start; padding: 27px 0px; border-bottom: 1px solid var(--line); }
.accepted-decision h4, .accepted-decision p { margin: 0px; }
.accepted-decision-label { color: var(--green); font-size: 11px; font-weight: 800; letter-spacing: 0.08em; }
.accepted-decision-reason { color: var(--muted); font-size: 13px; line-height: 1.55; }
.accepted-decision-facts { display: grid; gap: 10px; }
.accepted-decision-facts > div { display: grid; grid-template-columns: 135px 1fr; gap: 14px; }
.accepted-decision-facts span, .accepted-decision-facts small { color: var(--muted); font-size: 11px; }
.outcome-result-heading { display: flex; align-items: baseline; justify-content: space-between; padding: 34px 0px 18px; }
.outcome-result-heading h4 { margin: 0px; font-size: 22px; }
