}
.gate-strip, .capability-matrix { display: none; }
.evidence-download { margin-top: 28px; }
footer { display: flex; width: min(1420px, 100% - 76px); align-items: center; justify-content: space-between; margin: 0px auto; padding: 18px 0px 24px; border-top: 1px solid var(--line); color: var(--muted); font-size: 11px; }
@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after { scroll-behavior: auto !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}

